import MANIFEST from './optimized-media.json'

/**
 * Self-hosted, pre-optimized copies of heavy images from the
 * Siin-Notion GitHub image bed (served through jsDelivr).
 * PNG -> WebP (same pixels, smaller). GIF -> MP4 + WebP poster.
 * Generated by scripts/optimize-notion-media.sh; see public/media/notion/.
 */
const BED_RE =
  /^https?:\/\/(?:cdn\.jsdelivr\.net\/gh\/Si+n?Xu\/Siin-Notion@[^/]+|raw\.githubusercontent\.com\/Si+n?Xu\/Siin-Notion\/[^/]+|github\.com\/Si+n?Xu\/Siin-Notion\/(?:raw|blob)\/[^/]+)\/img\/([^?#]+)/i

// width/height in the manifest are the ORIGINAL pixel sizes, so layout that
// depends on intrinsic size stays exactly the same after the swap.
const BY_LOCAL = Object.values(MANIFEST).reduce((acc, item) => {
  acc[item.src] = item
  if (item.poster) acc[item.poster] = item
  return acc
}, {})

export function resolveOptimizedMedia(url) {
  if (!url || typeof url !== 'string') return null
  if (url.startsWith('/media/notion/')) {
    return BY_LOCAL[url.split(/[?#]/)[0]] || null
  }
  const m = url.match(BED_RE)
  if (!m) return null
  let name = m[1]
  try {
    name = decodeURIComponent(name)
  } catch (e) {}
  return MANIFEST[name] || null
}

/** URL to use in an <img> (PNG -> WebP; GIF -> unchanged so callers can render video). */
export function optimizedImageUrl(url) {
  const hit = resolveOptimizedMedia(url)
  return hit && hit.type === 'image' ? hit.src : url
}
